<script setup>
import {computed,ref,toRaw} from 'vue';
import FormDialog from './FormDialog.vue';
import {api} from '../services/accounting.js';
import {errorText} from '../locales/accounting.js';
import {payrollErrors,payrollManualLabels} from '../locales/payroll.js';
import {emptyPayrollInput} from '../../../shared/payroll.js';
import {payrollAgreement,payrollAgreementFor} from '../../../shared/payroll-agreements.js';
import {useAccess} from '../composables/access.js';
import {useContext} from '../composables/context.js';
import {reportMoney as money} from '../services/report-format.js';
const props=defineProps({slip:Object,employees:Array,year:Number,month:Number,exerciseId:[String,Number]}),emit=defineEmits(['close','saved']),{can}=useAccess(),{selectedExercise}=useContext();
const employeeId=ref(String(props.slip?.employee_id||props.employees.find(row=>row.profile.active)?.id||props.employees[0]?.id||'')),year=ref(Number(props.slip?.period_from.slice(0,4)||props.year)),month=ref(Number(props.slip?.period_from.slice(5,7)||props.month)),kind=ref(props.slip?.kind||'monthly');
const readOnly=!can('accounting_write')||selectedExercise.value?.status!=='open'||props.slip&&props.slip.status!=='draft';
const employees=computed(()=>readOnly&&props.slip?[{id:props.slip.employee_id,profile:props.slip.employee_snapshot.profile,version:props.slip.employee_snapshot.version}]:props.employees);
const person=computed(()=>employees.value.find(row=>String(row.id)===employeeId.value));
const input=ref(props.slip?structuredClone(toRaw(props.slip.input)):emptyPayrollInput(person.value.profile,year.value,month.value)),calculation=ref(props.slip?.calculation||null),busy=ref(false),error=ref(''),requestId=crypto.randomUUID();
const dirty=computed(()=>!calculation.value||JSON.stringify(input.value)!==JSON.stringify(calculation.value.input));
const agreement=computed(()=>payrollAgreementFor(person.value.profile.agreement_code)||payrollAgreement);
const amountFields=computed(()=>[['base_salary','Salario base por unidad'],['seniority',agreement.value.seniority_label+' por unidad'],['attendance_rate','Prima de asistencia por día'],['extra_annual','Importe anual de las '+agreement.value.extra_count+' extras'],['advance','Anticipos'],['other_deductions','Otras deducciones']]);
function defaults(){if(readOnly)return;input.value=emptyPayrollInput(person.value.profile,year.value,month.value,kind.value);calculation.value=null;}
function addEarning(){input.value.earnings.push({id:crypto.randomUUID(),description:'',amount:'0.00'});}
function body(){return {exercise_id:props.exerciseId,employee_id:person.value.id,employee_version:person.value.version,version:props.slip?.version||0,request_id:requestId,input:{...input.value,attendance_days:input.value.attendance_days===''?null:input.value.attendance_days,attendance_override:input.value.attendance_override===''?null:input.value.attendance_override,irpf_rate:input.value.irpf_rate===''?null:input.value.irpf_rate,accident_rate:input.value.accident_rate===''?null:input.value.accident_rate}};}
async function calculate(save=false){busy.value=true;error.value='';try{const payload=body(),data=await api('/payroll/'+(save?'slips'+(props.slip?'/'+props.slip.id:''):'preview'),{method:save&&props.slip?'PUT':'POST',body:payload,timeoutMs:45000});if(save){emit('saved',data);return;}calculation.value=data.calculation;input.value=structuredClone(data.calculation.input);}catch(cause){error.value=payrollErrors[cause.code]||errorText(cause);}finally{busy.value=false;}}
</script>
<template><FormDialog class="payroll-dialog" :title="slip?'Nómina · '+slip.employee_snapshot.profile.name:'Nueva nómina'" :busy="busy" @close="emit('close')"><form class="payroll-form" @submit.prevent="calculate(true)"><p v-if="error" class="notice error-notice" role="alert">{{ error }}</p><p v-if="slip&&slip.employee_snapshot.version!==person?.version&&!readOnly" class="notice">La ficha ha cambiado. Revisa las condiciones o carga de nuevo sus valores.</p><fieldset :disabled="busy||readOnly"><div class="payroll-fields"><label>Trabajador<select v-model="employeeId" aria-label="Trabajador de la nómina" :disabled="!!slip" @change="defaults"><option v-for="row in employees" :key="row.id" :value="String(row.id)">{{ row.profile.name }} · {{ row.profile.code }}</option></select></label><label>Año<input v-model.number="year" type="number" min="2000" max="2099" @change="defaults" /></label><label>Mes<select v-model.number="month" aria-label="Mes de la nómina" @change="defaults"><option v-for="m in 12" :key="m" :value="m">{{ String(m).padStart(2,'0') }}</option></select></label><label>Tipo<select v-model="kind" aria-label="Tipo de nómina" @change="defaults"><option value="monthly">Nómina mensual</option><option value="extra">Paga extraordinaria</option></select></label></div><div class="actions"><button class="button small" type="button" @click="defaults">Cargar condiciones de la ficha</button></div><div class="payroll-fields"><label>Desde<input v-model="input.period_from" type="date" required /></label><label>Hasta<input v-model="input.period_to" type="date" required /></label><label>Modalidad de cálculo<select v-model="input.mode" aria-label="Modalidad de nómina"><option value="general_2026">Régimen general · Cálculo ordinario 2026</option><option value="reviewed">Bases y cuotas revisadas</option></select></label><label>Unidades de salario<input v-model.number="input.units" type="number" min="1" max="31" aria-label="Unidades de salario" /><small>{{ person.profile.salary_unit==='daily'?'Días de salario diario':'Días sobre el salario mensual (mes completo: 30)' }}</small></label><label v-if="input.kind==='monthly'">Días de prima de asistencia<input v-model.number="input.attendance_days" type="number" min="0" max="31" aria-label="Días de asistencia" placeholder="Indicar días efectivos" /></label><label v-if="input.kind==='monthly'">Prima de asistencia revisada (€)<input v-model="input.attendance_override" inputmode="decimal" placeholder="Opcional · Vacaciones u otro ajuste" /></label><label v-for="[key,label] in input.kind==='monthly'?amountFields:amountFields.filter(row=>['advance','other_deductions'].includes(row[0]))" :key="key">{{ label }} (€)<input v-model="input[key]" inputmode="decimal" :aria-label="label" /></label><label v-if="input.kind==='extra'">Importe de la paga extra (€)<input v-model="input.extra_amount" inputmode="decimal" aria-label="Importe paga extra" /></label><label>Tipo de IRPF revisado (%)<input v-model="input.irpf_rate" inputmode="decimal" aria-label="IRPF de la nómina" /></label><label v-if="input.kind==='monthly'">Tarifa AT/EP (%)<input v-model="input.accident_rate" inputmode="decimal" /></label></div><label v-if="input.kind==='monthly'" class="checkbox-label"><input v-model="input.prorated" type="checkbox" />{{ agreement.prorated_label }}</label><label v-if="input.kind==='extra'" class="checkbox-label"><input v-model="input.extra_cotized" type="checkbox" />Esta paga ya ha cotizado mediante las prorratas de las nóminas ordinarias.</label><p class="payroll-help">{{ agreement.name }} · {{ agreement.code }}. {{ agreement.extra_help }}</p><h3>Otros complementos salariales</h3><div v-if="input.earnings.length" class="table-wrap"><table><thead><tr><th>Concepto</th><th>Importe (€)</th><th></th></tr></thead><tbody><tr v-for="(row,index) in input.earnings" :key="row.id"><td><input v-model="row.description" maxlength="160" :aria-label="'Complemento '+(index+1)" /></td><td><input v-model="row.amount" inputmode="decimal" :aria-label="'Importe complemento '+(index+1)" /></td><td><button class="button small" type="button" @click="input.earnings.splice(index,1)">Eliminar</button></td></tr></tbody></table></div><button type="button" class="button small" @click="addEarning">Añadir complemento</button><p class="payroll-help">Los complementos ordinarios se incluyen en las bases de cotización e IRPF. Para bajas, altas parciales, horas extra, retribución en especie, exenciones u otras incidencias, selecciona bases y cuotas revisadas y completa los importes comprobados.</p><template v-if="input.mode==='reviewed'"><h3>Bases y cuotas comprobadas (€)</h3><div class="payroll-fields"><label>Prorrata extras para cotización<input v-model="input.reviewed_extra_proration" inputmode="decimal" /></label><label>Diferencia de redondeo del resumen<input v-model="input.employer_rounding" inputmode="decimal" /></label></div><div class="payroll-fields"><label v-for="(label,key) in payrollManualLabels" :key="key">{{ label }}<input v-model="input.manual[key]" inputmode="decimal" /></label></div></template><label class="checkbox-label"><input v-model="input.special_case" type="checkbox" />Hay incidencias que requieren revisión específica.</label><label class="payroll-notes">Notas<textarea v-model="input.notes" rows="2" maxlength="2000"></textarea></label><label class="checkbox-label"><input v-model="input.confirmed" type="checkbox" />He revisado devengos, convenio, fechas, bases, cuotas, IRPF y las incidencias de este período.</label></fieldset><div v-if="calculation" class="payroll-preview"><p v-if="dirty" class="notice">Recalcula para actualizar el resultado con los cambios.</p><div v-if="calculation.issues.length" class="notice tax-warning"><strong>Revisión pendiente</strong><ul><li v-for="issue in calculation.issues" :key="issue">{{ payrollErrors[issue]||issue }}</li></ul></div><div class="payroll-totals"><div><small>Total devengado</small><strong>{{ money(calculation.totals.gross) }} €</strong></div><div><small>Deducciones</small><strong>{{ money(calculation.totals.deductions) }} €</strong></div><div><small>Líquido a percibir</small><strong>{{ money(calculation.totals.net) }} €</strong></div><div><small>Coste empresa</small><strong>{{ money(calculation.totals.company_cost) }} €</strong></div></div><div class="table-wrap"><table><thead><tr><th>Cotización</th><th class="amount">Base</th><th class="amount">Trabajador</th><th class="amount">Empresa</th></tr></thead><tbody><tr v-for="row in calculation.contributions" :key="row.code"><td>{{ row.label }}</td><td class="amount">{{ money(row.base) }}</td><td class="amount">{{ money(row.employee) }}</td><td class="amount">{{ money(row.employer) }}</td></tr></tbody></table></div></div><div class="dialog-actions"><button class="button" type="button" :disabled="busy" @click="emit('close')">Cerrar</button><template v-if="!readOnly"><button class="button" type="button" :disabled="busy" @click="calculate(false)">Recalcular nómina</button><button class="button primary" :disabled="busy">Guardar borrador de nómina</button></template></div></form></FormDialog></template>
